-- 4M transaction-level US foreign assistance records -- who got aid money, from which agency, for what, by country and year.
-- Auto-generated by scripts/gen_evidence_pages.py: 3,967,456 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column FISCAL_YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "FISCAL_YEAR" as year, count(*) as records
from THE_LIBRARY.GOVERNMENT_SPENDING.FOREIGN_AID_TRANSACTIONS
group by 1
order by 1
limit 1000
